system_a_kql:
let TimeRange = 3d;
let FirstSeenProcesses = 
    SecurityEvent
    | where TimeGenerated >= ago(TimeRange)
    | summarize FirstSeen=min(TimeGenerated) by ProcessName=ActingProcessName, DvcHostname;
let ProcessCounts = 
    SecurityEvent
    | where TimeGenerated >= ago(TimeRange)
    | summarize Count=dcount(DvcHostname) by ProcessName=ActingProcessName;
FirstSeenProcesses
| join kind=inner (ProcessCounts) on ProcessName
| order by Count asc, FirstSeen asc
| project ProcessName, DvcHostname, FirstSeen, Count

