system_a_kql:
let baselineWindow = 1d;
let spikeWindow = 5m;
let thresholdMultiplier = 5;
NetworkSession
| where NetworkProtocol == "SMB"
| summarize BaselineCount = count() by SrcHostname, bin(TimeGenerated, baselineWindow)
| join kind=inner (
    NetworkSession
    | where NetworkProtocol == "SMB"
    | summarize SpikeCount = count() by SrcHostname, bin(TimeGenerated, spikeWindow)
) on SrcHostname
| where SpikeCount > BaselineCount * thresholdMultiplier
| project SrcHostname, BaselineCount, SpikeCount, TimeGenerated1=TimeGenerated1, TimeGenerated2=TimeGenerated2

